#!/usr/bin/env python3
"""Generates the XLSX test fixtures for tally-io-xlsx.

Run from anywhere with:  python3 -I tests/fixtures/xlsx/gen_fixtures.py

The workbooks reproduce the XML *shapes* Excel 365 and LibreOffice 7.x write
(shared strings with rich runs and phonetic guides, inline strings, shared
formulas, array formulas, `_xlfn.` prefixes, custom number formats, theme and
indexed colours, frozen panes, merges, defined names incl. `_xlnm.*`, hidden
rows/columns/sheets, the 1904 date system, ...). They are hand-written, not
saved by those applications. Output is deterministic (fixed timestamps).
Only the Python standard library is used.

The malicious corpus lives in `malicious/`. Inputs that would be large on
disk (20,000 real zip entries, 1 M cells) are generated by the Rust tests.
"""

import os
import struct
import zipfile

HERE = os.path.dirname(os.path.abspath(__file__))
BAD_DIR = os.path.join(HERE, "malicious")
EPOCH = (1980, 1, 1, 0, 0, 0)

DECL = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\r\n'
NS_MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS_R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
NS_MC = "http://schemas.openxmlformats.org/markup-compatibility/2006"
REL_PKG = "http://schemas.openxmlformats.org/package/2006/relationships"
RT = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/"
CT_MAIN = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"
CT_SHEET = "application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"
CT_SST = "application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"
CT_STYLES = "application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"
CT_THEME = "application/vnd.openxmlformats-officedocument.theme+xml"


def info(name, method=zipfile.ZIP_DEFLATED):
    zi = zipfile.ZipInfo(name, date_time=EPOCH)
    zi.compress_type = method
    zi.external_attr = 0o644 << 16
    return zi


def write_zip(path, entries):
    """entries: list of (name, bytes|str)."""
    with zipfile.ZipFile(path, "w") as z:
        for name, data in entries:
            if isinstance(data, str):
                data = data.encode("utf-8")
            z.writestr(info(name), data)


def esc(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def content_types(n_sheets, sst=True, extra=""):
    parts = [
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
        '<Default Extension="xml" ContentType="application/xml"/>',
        '<Override PartName="/xl/workbook.xml" ContentType="%s"/>' % CT_MAIN,
    ]
    for i in range(1, n_sheets + 1):
        parts.append('<Override PartName="/xl/worksheets/sheet%d.xml" ContentType="%s"/>' % (i, CT_SHEET))
    parts.append('<Override PartName="/xl/theme/theme1.xml" ContentType="%s"/>' % CT_THEME)
    parts.append('<Override PartName="/xl/styles.xml" ContentType="%s"/>' % CT_STYLES)
    if sst:
        parts.append('<Override PartName="/xl/sharedStrings.xml" ContentType="%s"/>' % CT_SST)
    parts.append('<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>')
    parts.append('<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>')
    return DECL + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">%s%s</Types>' % ("".join(parts), extra)


