def workbook_rels(n_sheets, sst=True):
    rels = []
    for i in range(1, n_sheets + 1):
        rels.append('<Relationship Id="rId%d" Type="%sworksheet" Target="worksheets/sheet%d.xml"/>' % (i, RT, i))
    n = n_sheets
    rels.append('<Relationship Id="rId%d" Type="%stheme" Target="theme/theme1.xml"/>' % (n + 1, RT))
    rels.append('<Relationship Id="rId%d" Type="%sstyles" Target="styles.xml"/>' % (n + 2, RT))
    if sst:
        rels.append('<Relationship Id="rId%d" Type="%ssharedStrings" Target="sharedStrings.xml"/>' % (n + 3, RT))
    return DECL + '<Relationships xmlns="%s">%s</Relationships>' % (REL_PKG, "".join(rels))


def workbook_xml(sheets, names="", date1904=False, active=0):
    """sheets: list of (name, state or None)."""
    sh = "".join(
        '<sheet name="%s" sheetId="%d"%s r:id="rId%d"/>'
        % (esc(n), i + 1, ' state="%s"' % st if st else "", i + 1)
        for i, (n, st) in enumerate(sheets)
    )
    pr = '<workbookPr%s defaultThemeVersion="166925"/>' % (' date1904="1"' if date1904 else "")
    return (
        DECL
        + '<workbook xmlns="%s" xmlns:r="%s" xmlns:mc="%s" mc:Ignorable="x15 xr xr6 xr10 xr2">' % (NS_MAIN, NS_R, NS_MC)
        + '<fileVersion appName="xl" lastEdited="7" lowestEdited="7" rupBuild="27425"/>'
        + pr
        + '<bookViews><workbookView xWindow="-110" yWindow="-110" windowWidth="19420" windowHeight="10300" activeTab="%d"/></bookViews>' % active
        + "<sheets>%s</sheets>" % sh
        + (("<definedNames>%s</definedNames>" % names) if names else "")
        + '<calcPr calcId="191029"/>'
        + "</workbook>"
    )


def sst_xml(items):
    """items: list of raw <si> inner XML strings."""
    return DECL + '<sst xmlns="%s" count="%d" uniqueCount="%d">%s</sst>' % (
        NS_MAIN, len(items), len(items), "".join("<si>%s</si>" % i for i in items)
    )


def sheet_xml(sheet_data, before="", after="", views='<sheetViews><sheetView workbookViewId="0"/></sheetViews>', cols=""):
    return (
        DECL
        + '<worksheet xmlns="%s" xmlns:r="%s" xmlns:mc="%s" mc:Ignorable="x14ac xr xr2 xr3" '
        'xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac">' % (NS_MAIN, NS_R, NS_MC)
        + before
        + views
        + '<sheetFormatPr defaultRowHeight="14.5" x14ac:dyDescent="0.35"/>'
        + cols
        + "<sheetData>%s</sheetData>" % sheet_data
        + after
        + '<pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/>'
        + "</worksheet>"
    )


