def c(ref, v=None, s=None, t=None, f=None, inner=None):
    attrs = ' r="%s"' % ref
    if s:
        attrs += ' s="%d"' % s
    if t:
        attrs += ' t="%s"' % t
    body = ""
    if f is not None:
        body += f
    if inner is not None:
        body += inner
    if v is not None:
        body += "<v>%s</v>" % v
    return "<c%s>%s</c>" % (attrs, body)


def row(r, cells, extra=""):
    return '<row r="%d"%s>%s</row>' % (r, extra, "".join(cells))


