def gen_prefixed():
    """Namespace-prefixed SpreadsheetML (Open XML SDK style), no content
    types, no sharedStrings, cells without `r`, rows without `r`."""
    wb = (
        DECL
        + '<x:workbook xmlns:x="%s" xmlns:r="%s"><x:sheets>' % (NS_MAIN, NS_R)
        + '<x:sheet name="Prefixed" sheetId="1" r:id="rId1"/></x:sheets></x:workbook>'
    )
    rels = DECL + '<Relationships xmlns="%s"><Relationship Id="rId1" Type="%sworksheet" Target="/xl/worksheets/data.xml"/></Relationships>' % (REL_PKG, RT)
    sheet = (
        DECL
        + '<x:worksheet xmlns:x="%s"><x:sheetData>' % NS_MAIN
        + '<x:row><x:c t="inlineStr"><x:is><x:t>a</x:t></x:is></x:c><x:c><x:v>2</x:v></x:c></x:row>'
        '<x:row><x:c/><x:c><x:f>B1*3</x:f><x:v>6</x:v></x:c></x:row>'
        "</x:sheetData></x:worksheet>"
    )
    write_zip(
        os.path.join(HERE, "prefixed-ns.xlsx"),
        [("xl/workbook.xml", wb), ("xl/_rels/workbook.xml.rels", rels), ("xl/worksheets/data.xml", sheet)],
    )


