def minimal(sheet1, sst=None, styles=None, workbook=None):
    entries = [
        ("[Content_Types].xml", content_types(1, sst=sst is not None)),
        ("_rels/.rels", ROOT_RELS),
        ("xl/workbook.xml", workbook or workbook_xml([("S", None)])),
        ("xl/_rels/workbook.xml.rels", workbook_rels(1, sst=sst is not None)),
        ("xl/styles.xml", styles or EXCEL_STYLES),
        ("xl/worksheets/sheet1.xml", sheet1),
    ]
    if sst is not None:
        entries.append(("xl/sharedStrings.xml", sst))
    return entries


def gen_zip_bomb():
    # 160 MiB of whitespace inside sheetData, deflated ~1000:1 (~160 KB).
    path = os.path.join(BAD_DIR, "zip-bomb.xlsx")
    with zipfile.ZipFile(path, "w") as z:
        for name, data in minimal(sheet_xml(""))[:-1]:
            z.writestr(info(name), data)
        zi = info("xl/worksheets/sheet1.xml")
        zi.compress_level = 9
        head = (DECL + '<worksheet xmlns="%s"><sheetData>' % NS_MAIN).encode()
        chunk = b" " * (16 * 1024 * 1024)
        with z.open(zi, "w") as f:
            f.write(head)
            for _ in range(10):
                f.write(chunk)
            f.write(b"</sheetData></worksheet>")


def gen_doctype():
    xxe = (
        DECL
        + '<!DOCTYPE worksheet [<!ENTITY xxe SYSTEM "file:///etc/passwd">]>'
        + '<worksheet xmlns="%s"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>&xxe;</t></is></c></row></sheetData></worksheet>' % NS_MAIN
    )
    write_zip(os.path.join(BAD_DIR, "doctype-xxe.xlsx"), minimal(xxe))
    lol = ['<!ENTITY lol "lol">']
    for i in range(1, 10):
        prev = "lol" if i == 1 else "lol%d" % (i - 1)
        lol.append('<!ENTITY lol%d "%s">' % (i, ("&%s;" % prev) * 10))
    laughs = DECL + "<!DOCTYPE lolz [%s]>" % "".join(lol) + '<sst xmlns="%s"><si><t>&lol9;</t></si></sst>' % NS_MAIN
    good = sheet_xml(row(1, [c("A1", 0, None, "s")]))
    write_zip(os.path.join(BAD_DIR, "billion-laughs.xlsx"), minimal(good, sst=laughs))
    styles = DECL + '<!DOCTYPE x [<!ENTITY e SYSTEM "http://127.0.0.1:9/x">]><styleSheet xmlns="%s">&e;</styleSheet>' % NS_MAIN
    write_zip(os.path.join(BAD_DIR, "doctype-in-styles.xlsx"), minimal(good, styles=styles))
    wb = DECL + '<!DOCTYPE workbook SYSTEM "http://127.0.0.1:9/wb.dtd"><workbook xmlns="%s" xmlns:r="%s"><sheets><sheet name="S" sheetId="1" r:id="rId1"/></sheets></workbook>' % (NS_MAIN, NS_R)
    write_zip(os.path.join(BAD_DIR, "doctype-in-workbook.xlsx"), minimal(good, workbook=wb))


def gen_deep_nesting():
    n = 100_000
    inner = "<r>" * n + "<t>deep</t>" + "</r>" * n
    sheet = sheet_xml(row(1, ['<c r="A1" t="inlineStr"><is>%s</is></c>' % inner]))
    write_zip(os.path.join(BAD_DIR, "deep-nesting.xlsx"), minimal(sheet))
    attrs = " ".join('a%d="x"' % i for i in range(300))
    sheet = sheet_xml(row(1, ['<c r="A1" %s><v>1</v></c>' % attrs]))
    write_zip(os.path.join(BAD_DIR, "many-attributes.xlsx"), minimal(sheet))


def gen_huge_refs():
    """Logical bombs: absurd `r` attributes, a repeated far-away cell, a
    column range up to 2^32, a frozen pane past the grid. Nothing here may
    allocate per referenced (rather than per written) cell."""
    cells = []
    for i in range(50_000):
        cells.append('<c r="XFD1048576"><v>%d</v></c>' % i)
    cells.append('<c r="A99999999999999999999"><v>1</v></c>')
    cells.append('<c r="%s1"><v>1</v></c>' % ("Z" * 5000))
    rows = (
        '<row r="1048576">%s</row>' % "".join(cells)
        + '<row r="4294967297"><c><v>1</v></c></row>'
        + '<row r="1048577" ht="1e308" customHeight="1"><c r="A1048577"><v>1</v></c></row>'
    )
    sheet = sheet_xml(
        rows,
        before='<dimension ref="A1:XFD1048576"/>',
        views='<sheetViews><sheetView workbookViewId="0"><pane xSplit="1e300" ySplit="99999999999" state="frozen"/></sheetView></sheetViews>',
        cols='<cols><col min="1" max="4294967295" width="1e308" customWidth="1" style="2"/></cols>',
        after='<mergeCells count="2"><mergeCell ref="A1:XFD1048576"/><mergeCell ref="A1:XFE9"/></mergeCells>',
    )
    write_zip(os.path.join(BAD_DIR, "huge-refs.xlsx"), minimal(sheet))


def gen_big_text():
    big = "x" * (17 * 1024 * 1024)
    sheet = sheet_xml(row(1, ['<c r="A1" t="inlineStr"><is><t>%s</t></is></c>' % big]))
    write_zip(os.path.join(BAD_DIR, "big-text.xlsx"), minimal(sheet))


def gen_lying_eocd():
    """A small, valid package whose end-of-central-directory record claims
    20,000 entries; it must be rejected before the zip index is built."""
    path = os.path.join(BAD_DIR, "eocd-20k-entries.xlsx")
    write_zip(path, minimal(sheet_xml(row(1, [c("A1", 1)]))))
    data = bytearray(open(path, "rb").read())
    i = data.rfind(b"PK\x05\x06")
    struct.pack_into("<HH", data, i + 8, 20_000, 20_000)
    open(path, "wb").write(bytes(data))


